function renderMore(){const entries=[['configuracoes','settings','ConfiguraÃ§Ãµes','Dados da clÃ­nica, usuÃ¡rios, permissÃµes e sua conta.'],['suporte','message','Suporte','Converse com a equipe do Evoluna dentro do sistema.'],['marketing','sparkles','Marketing digital','AÃ§Ãµes e materiais para fortalecer a presenÃ§a da clÃ­nica.'],['financeiro','wallet','Financeiro','Receitas, despesas e valores a receber.'],['relatorios','chart','RelatÃ³rios','Indicadores e exportaÃ§Ã£o dos registros.'],['tour','sparkles','ConheÃ§a a plataforma','Um tour pelos recursos do Evoluna.']];return heading('Evoluna +','Acesse as configuraÃ§Ãµes e os demais recursos da plataforma.')+`<div class="module-grid">${entries.map(([id,i,title,description])=>{const tour=id==='tour',tag=tour?'button':'a';return `<${tag} class="report-box more-card" ${tour?'type="button" data-action="tour"':`href="#${id}"`} aria-labelledby="more-card-${id}"><span class="kpi-icon">${icon(i,18)}</span><span class="more-card-content"><strong class="more-card-title" id="more-card-${id}">${title}</strong><span class="more-card-description">${description}</span><span class="button">${tour?'Iniciar tour':'Abrir'} ${icon('arrow',13)}</span></span></${tag}>`}).join('')}</div>`}
