function render(){if(!window.EvolunaCloud?.ready)return;const focused=!!callState&&route==='teleconsultas';document.body.classList.toggle('consultation-focus',focused);document.body.classList.toggle('smile-focus',route==='sorriso');window.SmileWorkspace?.cleanup();if(!focused)window.SessionChat?.cleanup();if(callState&&route==='teleconsultas'&&$('#live-stage')&&$('#session-notes')){renderNav();window.SessionNotes.refresh();window.SessionChat?.mount();return}if(window.VideoRoom)window.VideoRoom.cleanup();renderNav();$('#content').innerHTML=(renderers[route]||renderHome)();mountDesktopDocumentPreview();window.SmileWhitening.mount();window.SmileWorkspace?.mount();if(route==='sorriso')window.SmileStudioHost?.mount();if(callState&&route==='teleconsultas'){updateTimer();window.SessionChat?.mount();}document.title=`${route==='paciente'?'Perfil do paciente':route==='prontuario'?'ProntuÃ¡rio':route==='prontuarios'?'Pacientes':navItems.find(n=>n[0]===route)?.[2]||'VisÃ£o geral'} Â· Evoluna Odonto Â· Sorriso com IA`}
function navigate(r){let base=r.split('?')[0];if(!renderers[base]){r='inicio';base=r}if(location.hash==='#'+r){route=base;render()}else location.hash=r;$('#sidebar').classList.remove('open')}
