function patientLookupResults(query='') {
  const normal=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const q=normal(query.trim());
  const list=db.patients.filter(p=>normal(`${p.name} ${p.email} ${p.phone} ${p.cpf||''}`).includes(q)||(q.replace(/\D/g,'').length>=3&&`${p.phone} ${p.cpf||''}`.replace(/\D/g,'').includes(q.replace(/\D/g,''))));
  return list.map(p=>`<button class="search-result" data-action="patient" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.phone)} Â· ${esc(p.email)}</small></span>${icon('arrow',14)}</button>`).join('')||'<div class="empty"><h3>Nenhum paciente encontrado.</h3><p>Busque por nome, telefone ou e-mail.</p></div>';
}
