document.addEventListener('change',e=>{const el=e.target;if(el.name==='smile-procedure'){smile.procedure=el.value;smile.generated=false;if(window.MagicSmile?.settingsChanged()){render();return}if(smile.photo){if(window.Veneer.state().selecting)render();else window.Veneer.apply();return}render();return}switch(el.id){case'patient-status':patientStatus=el.value;$('#patients-list').innerHTML=patientCards();break;case'agenda-status':agendaStatus=el.value;render();break;case'finance-filter':financeFilter=el.value;$('#finance-rows').innerHTML=transactionRows();break;case'smile-patient':smile.patient=el.value;break;case'document-type':if(docTypes.includes(el.value)){documentType=el.value;resetPreparedDocument();documentEditorModal()}break;case'document-patient':if(db.patients.some(p=>p.id===el.value)){documentPatient=el.value;resetPreparedDocument();documentEditorModal()}break;case'smile-photo':{const f=el.files[0];if(!f)return;if(!['image/jpeg','image/png'].includes(f.type)||f.size>4*1024*1024){toast('Escolha uma imagem JPG ou PNG com atÃ© 4 MB.');return}window.Veneer.read(f);break}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['patient-form','appointment-form','note-form','treatment-form','transaction-form','settings-form','quick-smile-form','support-intake-form','support-message-form','team-user-form'].includes(f.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(f));switch(f.id){case'quick-smile-form':{const phone=normalizePhone(v.phone);if(phone.length<10){$('#quick-smile-message').textContent='Informe um telefone com DDD.';return}let p=db.patients.find(p=>normalizePhone(p.phone)===phone);if(!p){p={id:uid('p'),code:`PAC-${String(Date.now()).slice(-6)}`,name:String(v.name).trim(),birth:'',phone:v.phone,email:'',status:'Ativo',color:db.patients.length%4,procedure:'Planejamento do sorriso',plan:'Particular',allergies:'',notes:'Cadastro rÃ¡pido pelo Sorriso IA.',last:dateKey(),teeth:{},history:[],treatments:[],createdBy:db.settings.dentistId};db.patients.unshift(p);if(!await activity(`${p.name}: cadastro rÃ¡pido criado pelo Sorriso IA.`,'users'))return}else if(String(v.name).trim()&&!p.name)p.name=String(v.name).trim();smile.patient=p.id;closeModal();navigate('sorriso');render();toast(p.code?'Paciente selecionado.':'Cadastro localizado pelo telefone.');break}case'support-intake-form':{operationalState();const ticket={id:uid('sup'),protocol:`SUP-${new Date().getFullYear()}-${String(db.supportTickets.length+1).padStart(5,'0')}`,area:v.area,kind:v.kind,priority:v.priority,description:v.description,status:'Aguardando atendimento',createdAt:new Date().toISOString(),messages:[]};db.supportTickets.unshift(ticket);if(!await activity(`${ticket.protocol}: suporte aberto em ${ticket.area}.`,'message'))return;closeModal();navigate('suporte');render();break}case'support-message-form':{const ticket=db.supportTickets.find(t=>t.id===f.dataset.id);if(!ticket)return;ticket.messages=ticket.messages||[];ticket.messages.push({id:uid('msg'),text:v.message,from:'user',createdAt:new Date().toISOString()});ticket.updatedAt=new Date().toISOString();if(!await save())return;render();break}case'team-user-form':{operationalState();const editing=db.teamUsers.find(u=>u.id===f.dataset.id),permissions=userPermissions(editing);for(const key of Object.keys(permissions))permissions[key]=f.elements[key]?.checked||false;const user=editing||{id:uid('usr'),code:`USR-N2-${String(db.teamUsers.length+1).padStart(4,'0')}`,role:'N2',status:'Convite pendente',createdAt:new Date().toISOString()};Object.assign(user,{name:v.name,email:String(v.email).trim().toLowerCase(),phone:v.phone||'',permissions,updatedAt:new Date().toISOString()});if(!editing)db.teamUsers.push(user);if(!await activity(`${user.name}: usuÃ¡rio N2 ${editing?'atualizado':'cadastrado'}; convite pendente.`,'shield'))return;closeModal();render();toast('UsuÃ¡rio e permissÃµes salvos.');break}case'patient-form':{const editing=f.dataset.id;const p=editing?patient(editing):{id:uid('p'),code:`PAC-${String(Date.now()).slice(-6)}`,createdBy:db.settings.dentistId,color:db.patients.length%4,last:dateKey(),teeth:{},history:[],treatments:[]};Object.assign(p,v);if(!editing)db.patients.unshift(p);if(!await activity(`${p.name}: cadastro ${editing?'atualizado':'criado'}.`,'users'))return;closeModal();render();toast(editing?'Cadastro atualizado.':'Paciente cadastrado.');break}case'appointment-form':{const overlapping=db.appointments.filter(a=>a.date===v.date&&a.status!=='Cancelado'&&timeMinutes(a.time)<timeMinutes(v.time)+Number(v.duration)&&timeMinutes(v.time)<timeMinutes(a.time)+Number(a.duration));if(overlapping.some(a=>a.patient===v.patient)){const message='Cliente jÃ¡ agendado para esta data e horÃ¡rio.';$('#appointment-error').textContent=message;window.alert(message);f.elements.time.focus();return}const clash=overlapping.some(a=>a.professional===v.professional);if(clash){$('#appointment-error').textContent='Este profissional jÃ¡ tem uma consulta nesse intervalo. Escolha outro horÃ¡rio.';return}db.appointments.push({...v,id:uid('a'),duration:Number(v.duration)});selectedDate=v.date;if(!await activity(`Consulta de ${patient(v.patient).name} agendada para ${prettyDate(v.date)} Ã s ${v.time}.`,'calendar'))return;closeModal();navigate('agenda');render();toast('Agendamento salvo.');break}case'note-form':{const p=patient(f.dataset.id);p.history.unshift({title:v.title,date:v.date,text:v.text});p.last=v.date;if(!await save())return;closeModal();patientTab='evolucao';render();toast('EvoluÃ§Ã£o salva no prontuÃ¡rio.');break}case'treatment-form':patient(f.dataset.id).treatments.push({...v,value:Number(v.value)});if(!await save())return;closeModal();render();toast('Procedimento adicionado ao plano.');break;case'transaction-form':{const {situation,...data}=v;db.transactions.unshift({...data,id:uid('f'),value:Number(v.value),status:situation==='pending'?'Pendente':v.kind==='Receita'?'Recebido':'Pago'});if(!await activity(`LanÃ§amento demonstrativo: ${v.description}.`,'wallet'))return;closeModal();render();toast('LanÃ§amento salvo.');break}case'settings-form':Object.assign(db.settings,v);operationalState();if(!await save())return;render();toast('InformaÃ§Ãµes da clÃ­nica atualizadas.');break}});
function timeMinutes(t){const[h,m]=t.split(':').map(Number);return h*60+m}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal()}if(e.key==='Escape'){closeModal();$('#tour-root').innerHTML='';$('#sidebar').classList.remove('open')}if(e.key==='Tab'&&$('.modal')){const list=$$('button,a,input,select,textarea', $('.modal')).filter(el=>!el.disabled&&el.type!=='hidden');if(list.length){if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus()}}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();if(innerWidth<801&&$('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('[data-action="menu"]'))$('#sidebar').classList.remove('open')});
route=location.hash.slice(1).split('?')[0]||'inicio';if(!renderers[route])route='inicio';
window.EvolunaApp={empty:emptyDatabase,get:()=>db,set:value=>{db=value;operationalState();const kept=window.EvolunaCloud.retainPatientSelections(db.patients,{selectedPatient,documentPatient,smilePatient:smile.patient});selectedPatient=kept.selectedPatient;documentPatient=kept.documentPatient;smile.patient=kept.smilePatient;},render,stop:()=>{documentDraftText=null;certificate.editing=false;window.SessionNotes?.resetDrafts();window.DocumentActions?.clearImageCache();window.SessionChat?.cleanup(true);document.body.classList.remove('consultation-focus','smile-focus');window.SmileWorkspace?.cleanup();window.VideoRoom?.end();window.Veneer?.cancel();callState=null;smile={procedure:'clareamento',mode:'photo',patient:'',shade:'BL1',alignment:65,shape:50,compare:50,photo:null,generated:false};closeModal();}};
window.EvolunaCloud.boot();

document.addEventListener('focusin',e=>{if(e.target.id==='smile-patient-search'){const results=$('#smile-patient-results');results.innerHTML=smilePatientResults(e.target.value);results.hidden=false;e.target.setAttribute('aria-expanded','true')}});
document.addEventListener('click',e=>{if(!e.target.closest('.smile-planning-panel')){const results=$('#smile-patient-results');if(results){results.hidden=true;$('#smile-patient-search')?.setAttribute('aria-expanded','false')}}});
document.addEventListener('keydown',e=>{if(e.target.id!=='smile-patient-search')return;const results=$('#smile-patient-results');if(e.key==='Escape'){results.hidden=true;e.target.setAttribute('aria-expanded','false')}if(e.key==='ArrowDown'&&!results.hidden){e.preventDefault();results.querySelector('button')?.focus()}if(e.key==='Enter'&&!results.hidden){e.preventDefault();results.querySelector('button')?.click()}});

// Atualiza o dia ao retomar a aba e na virada da meia-noite, sem refazer formulÃ¡rios.
let displayedDay=dateKey();
function refreshCurrentDay(){const current=dateKey();if(current===displayedDay)return false;const previous=displayedDay;displayedDay=current;if(selectedDate===previous)selectedDate=current;if(window.EvolunaCloud?.ready&&['inicio','agenda'].includes(route)&&!document.querySelector('.modal')&&!document.querySelector('input:focus,textarea:focus,select:focus'))render();return true}
window.addEventListener('focus',refreshCurrentDay);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCurrentDay()});
for(const event of ['click','submit'])document.addEventListener(event,refreshCurrentDay,true);
setInterval(refreshCurrentDay,30000);
